with open("arrow/arrow.py", "r") as f:
    lines = f.readlines()

# Print lines with context for each pattern
patterns = ["dateutil_tz.tzutc()", "dateutil_tz.tzlocal()", "parser.TzinfoParser.parse(tzinfo)", 
            "parser.TzinfoParser.parse(tz_expr)"]
for pat in patterns:
    print(f"\n=== {pat} ===")
    for i, line in enumerate(lines):
        if pat in line:
            # Print surrounding context
            start = max(0, i-2)
            end = min(len(lines), i+3)
            for j in range(start, end):
                marker = ">>>" if j == i else "   "
                print(f"{marker} {j+1}: {lines[j]}", end='')
